// IdentityServiceServer is the server API for IdentityService service.
// All implementations must embed UnimplementedIdentityServiceServer
// for forward compatibility.
//
// IdentityService provides identity operations over gRPC and HTTP
type IdentityServiceServer interface {
	// Create a new user (called by auth service after registration)
	CreateUser(context.Context, *CreateUserRequest) (*CreateUserResponse, error)
	// List users with pagination
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	// Retrieve a user by ID
	GetUser(context.Context, *GetUserRequest) (*GetUserResponse, error)
	// Update an existing user
	UpdateUser(context.Context, *UpdateUserRequest) (*UpdateUserResponse, error)
	// Delete a user by ID
	DeleteUser(context.Context, *DeleteUserRequest) (*DeleteUserResponse, error)
	// Retrieve a user by email address
	GetUserByEmail(context.Context, *GetUserByEmailRequest) (*GetUserByEmailResponse, error)
	// List organizations a user belongs to
	ListSubjectPartitions(context.Context, *ListSubjectPartitionsRequest) (*ListSubjectPartitionsResponse, error)
	// Create a new organization
	CreatePartition(context.Context, *CreatePartitionRequest) (*CreatePartitionResponse, error)
	// List organizations with pagination
	ListOrganizations(context.Context, *ListOrganizationsRequest) (*ListOrganizationsResponse, error)
	// Retrieve an organization by ID
	GetOrganization(context.Context, *GetOrganizationRequest) (*GetOrganizationResponse, error)
	// Update an existing organization
	UpdateOrganization(context.Context, *UpdateOrganizationRequest) (*UpdateOrganizationResponse, error)
	// Sync external groups (Google/M365) to internal organisation groups
	SyncExternalGroups(context.Context, *SyncExternalGroupsRequest) (*SyncExternalGroupsResponse, error)
	// List groups for an organisation
	ListOrgGroups(context.Context, *ListOrgGroupsRequest) (*ListOrgGroupsResponse, error)
	// List the group ids a user belongs to within an organisation. This is the
	// canonical membership a product plane resolves at authorisation time so a
	// deprovisioned user stops resolving to any group.
	ListUserGroups(context.Context, *ListUserGroupsRequest) (*ListUserGroupsResponse, error)
	// Check if a user has access to a specific app
	CheckAppAccess(context.Context, *CheckAppAccessRequest) (*CheckAppAccessResponse, error)
	// Update access rules for an app (e.g. assign group to app)
	UpdateAppAccess(context.Context, *UpdateAppAccessRequest) (*UpdateAppAccessResponse, error)
	// Delete an organization by ID
	DeleteOrganization(context.Context, *DeleteOrganizationRequest) (*DeleteOrganizationResponse, error)
	// List available global services (registry)
	ListGlobalServices(context.Context, *ListGlobalServicesRequest) (*ListGlobalServicesResponse, error)
	// List enabled apps for an organisation
	ListEnabledApps(context.Context, *ListEnabledAppsRequest) (*ListEnabledAppsResponse, error)
	// Enable an app for an organisation (create policy)
	EnableApp(context.Context, *EnableAppRequest) (*EnableAppResponse, error)
	// Get app policy and access rules
	GetAppPolicy(context.Context, *GetAppPolicyRequest) (*GetAppPolicyResponse, error)
	// Update app configuration/policy
	UpdateAppConfig(context.Context, *UpdateAppConfigRequest) (*UpdateAppConfigResponse, error)
	// Disable an app for an organisation (delete policy)
	DisableApp(context.Context, *DisableAppRequest) (*DisableAppResponse, error)
	// Request access to an invite_required app for an organisation
	RequestAppAccess(context.Context, *RequestAppAccessRequest) (*RequestAppAccessResponse, error)
	// List app access requests (admin: all pending, org: own requests)
	ListAppAccessRequests(context.Context, *ListAppAccessRequestsRequest) (*ListAppAccessRequestsResponse, error)
	// Approve or deny an app access request (creates app_access_policies on approve)
	ReviewAppAccessRequest(context.Context, *ReviewAppAccessRequestRequest) (*ReviewAppAccessRequestResponse, error)
	// Invite a specific user to access an app within their org
	InviteUserToApp(context.Context, *InviteUserToAppRequest) (*InviteUserToAppResponse, error)
	// Revoke a specific user's direct app access
	RevokeUserAppAccess(context.Context, *RevokeUserAppAccessRequest) (*RevokeUserAppAccessResponse, error)
	// List all users with access to an app (direct grants + group members with total count)
	ListAppUsers(context.Context, *ListAppUsersRequest) (*ListAppUsersResponse, error)
	// Add a member to an organization
	AddSubject(context.Context, *AddSubjectRequest) (*AddSubjectResponse, error)
	// List all members of an organization
	ListSubjects(context.Context, *ListSubjectsRequest) (*ListSubjectsResponse, error)
	// Remove a member from an organization
	RemoveSubject(context.Context, *RemoveSubjectRequest) (*RemoveSubjectResponse, error)
	// Update member status in an organization
	SetSubjectStatus(context.Context, *SetSubjectStatusRequest) (*SetSubjectStatusResponse, error)
	// Create and send an invitation to join an organisation
	InviteSubject(context.Context, *InviteSubjectRequest) (*InviteSubjectResponse, error)
	// List pending/accepted/revoked invitations for an organisation
	ListInvitations(context.Context, *ListInvitationsRequest) (*ListInvitationsResponse, error)
	// Revoke a pending invitation
	RevokeInvitation(context.Context, *RevokeInvitationRequest) (*RevokeInvitationResponse, error)
	// Resend an invitation email
	ResendOrgInvitation(context.Context, *ResendOrgInvitationRequest) (*ResendOrgInvitationResponse, error)
	// Accept an invitation (public, token-authenticated)
	AcceptInvitation(context.Context, *AcceptInvitationRequest) (*AcceptInvitationResponse, error)
	// Get a user's billing subscriptions (proxied via BillingService)
	GetUserSubscriptions(context.Context, *GetUserSubscriptionsRequest) (*GetUserSubscriptionsResponse, error)
	// List roles defined for an organization
	ListRoles(context.Context, *ListRolesRequest) (*ListRolesResponse, error)
	// Create a custom role for an organization
	CreateRole(context.Context, *CreateRoleRequest) (*CreateRoleResponse, error)
	// Update a role's name, description, or permissions
	UpdateRole(context.Context, *UpdateRoleRequest) (*UpdateRoleResponse, error)
	// Delete a custom role
	DeleteRole(context.Context, *DeleteRoleRequest) (*DeleteRoleResponse, error)
	// Get user or org preferences
	GetPreferences(context.Context, *GetPreferencesRequest) (*GetPreferencesResponse, error)
	// Update user or org preferences
	UpdatePreferences(context.Context, *UpdatePreferencesRequest) (*UpdatePreferencesResponse, error)
	// List IP allowlist entries for an organization
	ListIPAllowlist(context.Context, *ListIPAllowlistRequest) (*ListIPAllowlistResponse, error)
	// Add an IP address or CIDR to the org allowlist
	AddIPAllowlist(context.Context, *AddIPAllowlistRequest) (*AddIPAllowlistResponse, error)
	// Remove an IP allowlist entry
	RemoveIPAllowlist(context.Context, *RemoveIPAllowlistRequest) (*RemoveIPAllowlistResponse, error)
	// Submit log event for persistence (mesh-based)
	LogEvent(context.Context, *LogEventRequest) (*LogEventResponse, error)
	// List paginated and filtered events
	ListEvents(context.Context, *ListEventsRequest) (*ListEventsResponse, error)
	// Get all events for a specific user
	GetUserEvents(context.Context, *GetUserEventsRequest) (*GetUserEventsResponse, error)
	// Initiate admin consent flow — returns redirect URL for the provider's consent page
	InitiateAdminConsent(context.Context, *InitiateAdminConsentRequest) (*InitiateAdminConsentResponse, error)
	// Complete admin consent — exchange auth code/consent for tokens and store provider
	CompleteAdminConsent(context.Context, *CompleteAdminConsentRequest) (*CompleteAdminConsentResponse, error)
	// Disconnect a directory provider from an organisation
	DisconnectProvider(context.Context, *DisconnectProviderRequest) (*DisconnectProviderResponse, error)
	// List connected directory providers for an organisation
	ListDirectoryProviders(context.Context, *ListDirectoryProvidersRequest) (*ListDirectoryProvidersResponse, error)
	// Trigger a directory sync for an organisation (manual or scheduled)
	TriggerDirectorySync(context.Context, *TriggerDirectorySyncRequest) (*TriggerDirectorySyncResponse, error)
	// Get directory sync status and history for an organisation
	GetDirectorySyncStatus(context.Context, *GetDirectorySyncStatusRequest) (*GetDirectorySyncStatusResponse, error)
	// Verify service health and database connectivity
	CheckHealth(context.Context, *CheckHealthRequest) (*CheckHealthResponse, error)
	// Ensure user identity exists from OAuth data (get or create)
	EnsureSubject(context.Context, *EnsureSubjectRequest) (*EnsureSubjectResponse, error)
	// Check organisation access policy (IP allowlist, allowed providers, allowed apps)
	// Called on every authenticated request with org context, and during auth flows
	// (CompleteOAuth, HandoffRedemption, Verify2FA) when org context is present.
	CheckOrgAccessPolicy(context.Context, *CheckOrgAccessPolicyRequest) (*CheckOrgAccessPolicyResponse, error)
	// Assign a role to an organisation member. Idempotent: duplicate
	// (organisation_id, user_id, role_id) triples succeed with already_assigned=true.
	// Used during tenant provisioning to grant the initial owner role, and from
	// the RBAC admin UI to add roles to existing members.
	GrantRole(context.Context, *GrantRoleRequest) (*GrantRoleResponse, error)
	// Remove a role assignment from an organisation member. Idempotent:
	// removing a non-existent assignment succeeds with not_assigned=true.
	RemoveMemberRole(context.Context, *RemoveMemberRoleRequest) (*RemoveMemberRoleResponse, error)
	// List all role assignments (role_id, granted_by, granted_at) for an
	// organisation member. Consumed by the UserPolicyBundle compiler in
	// Quorum to look up per-role permissions during signed-policy issuance.
	ListSubjectRoles(context.Context, *ListSubjectRolesRequest) (*ListSubjectRolesResponse, error)
	// Flatten an organisation member's assigned roles into a deduplicated
	// permission scope set. Used by Quorum's user_policy.Compile hot-swap.
	// When the user has no explicit roles, member_status drives the fallback:
	// "admin" -> ["*"], anything else -> ["authenticated"].
	ResolveMemberScopes(context.Context, *ResolveMemberScopesRequest) (*ResolveMemberScopesResponse, error)
	// Read organisation-scoped settings by key projection (empty keys = return all).
	// Carries tenant CIDR allowlists, api_key rotation policy, custom-scope linter
	// overrides, and any other per-org configuration that downstream domains need.
	GetOrgSettings(context.Context, *GetOrgSettingsRequest) (*GetOrgSettingsResponse, error)
	// Upsert organisation-scoped settings. Empty `value` deletes the row.
	// Companion writer to GetOrgSettings — used by the manage.quorum.ai admin UI
	// and by tenant_provisioning bootstrap.
	PutOrgSettings(context.Context, *PutOrgSettingsRequest) (*PutOrgSettingsResponse, error)
	// Grant or deny a single scope on one organisation member, layered on top of
	// their role union. A deny beats any grant (even wildcard) because
	// ResolveMemberScopes emits it as a negative marker. The general per-user
	// capability layer (the MCP connect gate, orbtr.mcp.connect, is a consumer).
	SetMemberCapabilityOverride(context.Context, *SetMemberCapabilityOverrideRequest) (*SetMemberCapabilityOverrideResponse, error)
	// List a member's per-user capability overrides.
	ListMemberCapabilityOverrides(context.Context, *ListMemberCapabilityOverridesRequest) (*ListMemberCapabilityOverridesResponse, error)
	// Remove a per-user capability override (idempotent).
	ClearMemberCapabilityOverride(context.Context, *ClearMemberCapabilityOverrideRequest) (*ClearMemberCapabilityOverrideResponse, error)
	// Stop a partition serving without destroying it. Idempotent: suspending a
	// suspended partition is a no-op that reports the same state.
	SuspendPartition(context.Context, *SuspendPartitionRequest) (*SuspendPartitionResponse, error)
	// Tear a partition down. Idempotent, and separate from Suspend because the
	// two are different decisions: one is reversible and one is not.
	DeletePartition(context.Context, *DeletePartitionRequest) (*DeletePartitionResponse, error)
	// Page through the partitions the caller may see. The caller's authority
	// bounds the result; the request carries no selector for whose to list.
	ListPartitions(context.Context, *ListPartitionsRequest) (*ListPartitionsResponse, error)
	// Read one partition.
	GetPartition(context.Context, *GetPartitionRequest) (*GetPartitionResponse, error)
	// Report where a partition is in provisioning. Distinct from GetPartition
	// because a partition can exist while its provisioning is still running, and
	// a caller that cannot tell those apart retries a completed provision or
	// serves an incomplete one.
	GetPartitionStatus(context.Context, *GetPartitionStatusRequest) (*GetPartitionStatusResponse, error)
	// Answer whether one subject holds a membership in one partition, and the
	// kind of subject that membership is for. The asker is an endpoint admitting
	// a mesh call whose principal asserts a partition other than the transport's,
	// and which holds no membership graph of its own to read.
	//
	// Mesh only, with no HTTP binding: the request names any subject and any
	// partition, so the answer is for a platform service deciding admission and
	// never for the subject asked about. Message types live in
	// resolve_membership.proto.
	//
	// The missing HTTP binding does not keep a caller out: rpchttp.RegisterAll
	// mounts POST /rpc/<fqn> for every handler in the registry it is given,
	// bound or not. What confines this operation is the scope its declaration
	// admits, so that declaration must admit only a service caller in the
	// control partition: a partition-scoped one would let a member of any
	// partition learn whether a subject belongs to another.
	ResolveMembership(context.Context, *ResolveMembershipRequest) (*ResolveMembershipResponse, error)
	mustEmbedUnimplementedIdentityServiceServer()
}

